import{_ as e,o as n,c as s,a2 as l}from"./chunks/framework.ClgMjOt7.js";const y=JSON.parse('{"title":"PallaSync 同期エンジン仕様","description":"設定暗号化、データ同期プロトコル、コンフリクト解決アルゴリズム","frontmatter":{"title":"PallaSync 同期エンジン仕様","description":"設定暗号化、データ同期プロトコル、コンフリクト解決アルゴリズム"},"headers":[],"relativePath":"architecture/pallasync.md","filePath":"architecture/pallasync.md","lastUpdated":1786168778000}'),t={name:"architecture/pallasync.md"};function o(c,a,i,r,p,d){return n(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="pallasync-同期エンジン仕様" tabindex="-1">PallaSync 同期エンジン仕様 <a class="header-anchor" href="#pallasync-同期エンジン仕様" aria-label="Permalink to &quot;PallaSync 同期エンジン仕様&quot;">​</a></h1><p><code>pallasync</code> パッケージは、設定データおよび状態を端末間で安全に保護・同期するためのカスタム同期サブシステムです。</p><hr><h2 id="主要クラス構成" tabindex="-1">主要クラス構成 <a class="header-anchor" href="#主要クラス構成" aria-label="Permalink to &quot;主要クラス構成&quot;">​</a></h2><ul><li><strong><code>PalleriaSyncManager</code></strong>: 同期処理の全体ライフサイクルを管轄。バックグラウンドイベントキューの管理およびリモートサーバー (<code>https://api.yunfi.f5.si</code>) との通信を制御。</li><li><strong><code>PallaSyncKeystore</code></strong>: <code>AndroidKeyStore</code> 内で生成した 256 ビット AES 鍵を用い、データの暗号化（AES-256-GCM / NoPadding）および改ざん検証タグ付与を実施。</li><li><strong><code>PallaSyncConflictResolver</code></strong>: 複数端末間やローカル/リモート間で設定データが衝突（コンフリクト）した際、タイムスタンプに基づく LWW (Last-Write-Wins) アルゴリズムで最終変更優先の競合解決を実行。</li><li><strong><code>PallaSyncEventApplier</code></strong>: 解決されたイベント（ブックマーク追加、テーマ変更、お気に入りタグ更新等）をローカル DataStore および Room DB に同期適用。</li></ul><hr><h2 id="暗号化シーケンス" tabindex="-1">暗号化シーケンス <a class="header-anchor" href="#暗号化シーケンス" aria-label="Permalink to &quot;暗号化シーケンス&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> [ 平文ペイロード ] ──&gt; [ PallaSyncKeystore ]</span></span>
<span class="line"><span>                              │ (Android KeyStore AES-256-GCM 鍵)</span></span>
<span class="line"><span>                              ▼</span></span>
<span class="line"><span>                        [ IV (12 bytes) ] + [ 暗号文 ] + [ GCM Tag (16 bytes) ]</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span> [ ネットワーク送信 / JSON ファイル出力 ] &lt;── (Base64 エンコード)</span></span></code></pre></div><ol><li>アプリ起動時に <code>AndroidKeyStore</code> から秘密鍵を安全に読み込み。</li><li>同期データまたはバックアップ JSON ファイルの書き出し時、ランダムな初期化ベクター (IV) を生成して暗号化。</li><li>読み込み時は GCM 認証タグを検証し、改ざんがないことを確認して安全に復号。</li></ol>`,9)])])}const S=e(t,[["render",o]]);export{y as __pageData,S as default};
